css:
/* Location columns: a photo behind a centred heading and a row of branch details. */
[data-bz-node="lc-band"] { position: relative; overflow: hidden; background: #0b3b57; padding-block: 125px 0; min-height: 455px; box-sizing: border-box; }
[data-bz-node="lc-head"], [data-bz-node="lc-row"] { position: relative; z-index: 1; }
[data-bz-section="location-columns"] .bz-block { padding-block: 0; }
[data-bz-node="lc-bg"] { position: absolute; inset: 0; z-index: 0; }
[data-bz-node="lc-bg"] .bz-container, [data-bz-node="lc-bg"] .bz-figure { position: absolute; inset: 0; max-width: none; margin: 0; padding: 0; }
[data-bz-node="lc-bg"] img { display: block; width: 100%; height: 100%; object-fit: cover; border-radius: 0; }
[data-bz-node="lc-row"] { width: 100%; max-width: min(90vw, 1440px); margin-inline: auto; }
[data-bz-section="location-columns"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #fff; letter-spacing: 0; }
[data-bz-section="location-columns"] [data-bz-node="lc-row"] { margin-top: 83px; }
[data-bz-section="location-columns"] h3 { margin: 0; text-align: center; font: 700 1.38rem / 1.2 var(--font-body); color: #fff; letter-spacing: 0; }
[data-bz-section="location-columns"] [data-bz-node^="lc-details"] .bz-text p { margin: 14px 0 0; text-align: center; font: 400 1.01rem / 1.43 var(--font-body); color: #fff; max-width: none; }
[data-bz-section="location-columns"] [data-bz-node^="lc-details"] a { color: var(--accent); text-decoration: none; }
@media (max-width: 1100px) { [data-bz-node="lc-band"] { padding-block: 72px 56px; min-height: 0; } [data-bz-section="location-columns"] [data-bz-node="lc-row"] > .bz-col { grid-column: span 6; } [data-bz-section="location-columns"] [data-bz-node="lc-row"] { row-gap: 36px; } }
@media (max-width: 640px) { [data-bz-section="location-columns"] [data-bz-node="lc-row"] > .bz-col { grid-column: 1 / -1; } [data-bz-section="location-columns"] h2 { font-size: 1.5rem; } }
